def build():
    out = []
    for n, row in enumerate(B, 1):
        lo, bl, typ, q, opts, ans, why = row[:7]
        it = {"id": f"i5_{n:03d}", "exam": "itil5", "lo": lo, "bl": bl, "type": typ, "q": q, "options": opts,
              "answer": ans, "why": why, "src": "xlrte-core", "status": "approved"}
        if len(row) > 7:
            it["stmts"] = row[7]
        out.append(it)
    here = os.path.dirname(os.path.abspath(__file__))
    json.dump(out, open(os.path.join(here, "..", "data", "items_itil5.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print(len(out), "ITIL items")


if __name__ == "__main__":
    build()
